// Safeguard marker: INSTAOPS_V2_EXTRACT — extracts media/captions to Supabase Primary (instaops_posts & instaops_media_assets) + Cloudinary, stops at DRAFT.
function readCfg(key, fallback) {
  var blocked = false;
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') {
      return { value: String($vars[key]), source: 'vars', blocked: false };
    }
  } catch (_) {}
  try {
    if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') {
      return { value: String($env[key]), source: 'env', blocked: false };
    }
  } catch (_) {
    blocked = true;
  }
  return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
}


var item = $input.first().json || {};
var body = item.body || item;

var postUuid = String(body.post_uuid || '').trim();
var postId = String(body.post_id || '').trim();
var sourceUrl = String(body.source_instagram_url || '').trim();
var authorized = body.authorized === true;
var uuidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(postUuid);
var urlOk = /^https:\/\/(www\.)?instagram\.com\/(p|reel|reels|tv)\/[A-Za-z0-9_-]+/i.test(sourceUrl);

var error = '';
var httpStatus = 202;
if (!uuidOk || !postId || !urlOk) {
  error = 'Valid permanent post_uuid, post_id, and canonical Instagram URL required.';
  httpStatus = 422;
} else if (!authorized) {
  error = 'Explicit owner authorization (authorized: true) is required.';
  httpStatus = 403;
}

var execId = String((typeof $execution !== 'undefined' && $execution && $execution.id) || '');
var reqId = String(body.request_id || '');
return [{
  json: {
    valid: !error,
    error: error,
    httpStatus: httpStatus,
    post_uuid: postUuid,
    post_id: postId,
    source_instagram_url: sourceUrl,
    expected_revision: String(body.expected_revision || '1'),
    request_id: reqId,
    job_id: String(body.job_id || ''),
    lock_key: String(body.lock_key || ('post:' + postUuid)),
    lock_owner: String(body.lock_owner || ''),
    worker_owner: 'w01:' + (execId || reqId || Date.now()),
    execution_id: execId,
    sb_url: readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co').value.replace(/\/$/, ''),
    dl_url: readCfg('DOWNLOADER_BASE_URL', 'https://ig-dowloader-nnnn.vercel.app').value.replace(/\/$/, ''),
    cld_cloud: readCfg('CLOUDINARY_CLOUD_NAME', 'djkkknb9k').value,
    started_at: new Date().toISOString()
  }
}];

var req = $('CODE | Validate & Safeguard').first().json;
var raw = $input.first().json || {};
var sc = raw.statusCode !== undefined ? Number(raw.statusCode) : (raw.error ? 0 : 200);
var body = raw.body !== undefined ? raw.body : raw;
var rows = Array.isArray(body) ? body : [body];
var row = rows[0] || {};
var acquired = !raw.error && sc < 300 && row.acquired === true;
return [{ json: { acquired: acquired, reason: String(row.reason || (raw.error && raw.error.message) || 'Lock acquisition failed'), post_uuid: req.post_uuid, post_id: req.post_id, lock_key: req.lock_key, worker_owner: req.worker_owner, job_id: req.job_id, sb_url: req.sb_url, dl_url: req.dl_url, execution_id: req.execution_id } }];

var raw = $input.first().json || {};
var body = raw.body !== undefined ? raw.body : raw;
var post = Array.isArray(body) ? body[0] : body;
var blocked = ['PUBLISHED', 'PUBLISHING', 'VERIFY_MANUALLY', 'DELETED', 'ARCHIVED', 'DELETING'];
var req=$('CODE | Validate & Safeguard').first().json;
var eligible = Boolean(!raw.error && Number(raw.statusCode)>=200 && Number(raw.statusCode)<300 && post && String(post.id)===req.post_uuid && String(post.post_id)===req.post_id && String(post.source_instagram_url)===req.source_instagram_url && Number(post.revision)===Number(req.expected_revision) && blocked.indexOf(post.status) === -1);
return [{ json: { eligible: eligible, post: post || {}, reason: !post || !post.id ? 'Active post not found' : ('Post status ' + post.status + ' blocks extraction') } }];

function isSafeHttpsRemoteUrl(raw) {
  try {
    var u = new URL(String(raw || '').trim());
    if (u.protocol !== 'https:') return false;
    var h = u.hostname.toLowerCase();
    if (!h || h === 'localhost' || h.endsWith('.local') || h.endsWith('.internal')) return false;
    if (/^(127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/.test(h)) return false;
    return (h.endsWith('.cdninstagram.com') || h.endsWith('.fbcdn.net')) && !u.username && !u.password && (!u.port || u.port === '443');
  } catch (_) { return false; }
}

function extractTags(caption, prefix) {
  if (!caption) return [];
  var out = [];
  var parts = String(caption).split(/\s+/);
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    if (p.startsWith(prefix) && p.length > 1) {
      var clean = prefix + p.slice(1).replace(/[^A-Za-z0-9_.]/g, '');
      if (clean.length > 1 && out.indexOf(clean) === -1) out.push(clean);
    }
  }
  return out.slice(0, 30);
}

var req = $('CODE | Validate & Safeguard').first().json;
var postRow = ($('CODE | Check Post Eligible').first().json || {}).post || {};
var raw = $input.first().json || {};
var netErr = Boolean(raw.error && raw.statusCode === undefined);
var sc = raw.statusCode !== undefined ? Number(raw.statusCode) : (netErr ? 0 : 200);
var dl = raw.body !== undefined ? raw.body : raw;
if (typeof dl === 'string') { try { dl = JSON.parse(dl); } catch (_) { dl = {}; } }
dl = dl || {};

function failObj(code, stage, msg) {
  return [{ json: { dl_ok: false, errCode: code, errStage: stage, errMsg: msg, uploadedAssets: [], items: [], nextIdx: 0, totalBytes: 0, imgCount: 0, vidCount: 0, metadata: {} } }];
}

if (netErr) return failObj('DOWNLOADER_UNAVAILABLE', 'FETCHING_SOURCE', String(raw.error.message || 'Downloader request failed'));
if (sc === 429) return failObj('UPSTREAM_RATE_LIMIT', 'FETCHING_SOURCE', String(dl.error || 'Downloader upstream rate limit reached'));
if (sc >= 300 || dl.ok !== true || String(dl.status || '').toLowerCase() !== 'ready') {
  return failObj('DOWNLOADER_NOT_READY', 'FETCHING_SOURCE', String(dl.error || ('Downloader returned status ' + String(dl.status || sc) + ' (ok=' + String(dl.ok) + ')')));
}

var rawItems = Array.isArray(dl.media) ? dl.media : Array.isArray(dl.items) ? dl.items : Array.isArray(dl.assets) ? dl.assets : [];
if (!rawItems.length && (dl.mediaUrl || dl.downloadUrl || dl.url)) {
  rawItems = [{ url: dl.mediaUrl || dl.downloadUrl || dl.url, type: dl.mediaType || dl.kind || postRow.media_type, expiresAt: dl.expiresAt || dl.expires_at || '' }];
}
if (rawItems.length < 1 || rawItems.length > 10) {
  return failObj('INVALID_MEDIA_COUNT', 'VALIDATING_MEDIA', 'Downloader returned ' + rawItems.length + ' items (must be 1-10).');
}

var nowMs = Date.now();
for (var m = 0; m < rawItems.length; m++) {
  var it = rawItems[m] || {};
  var mediaUrl = String(it.url || it.downloadUrl || it.media_url || it.secure_url || '').trim();
  if (!isSafeHttpsRemoteUrl(mediaUrl)) {
    return failObj('SSRF_BLOCKED', 'VALIDATING_MEDIA', 'Item ' + m + ' has unsafe or non-HTTPS remote URL.');
  }
  var expRaw = String(it.expiresAt || it.expires_at || dl.expiresAt || '').trim();
  if (expRaw) {
    var expMs = Date.parse(expRaw);
    if (Number.isFinite(expMs) && expMs <= nowMs) {
      return failObj('MEDIA_URL_EXPIRED', 'VALIDATING_MEDIA', 'Downloader temporary URL for item ' + m + ' already expired at ' + expRaw + '.');
    }
  }
}

var rawCaption = String(dl.caption || dl.text || '');
var captionStatus = rawCaption ? 'available' : String(dl.captionStatus || dl.caption_status || (dl.caption === '' ? 'empty' : 'unavailable'));
var effectiveCaption = String(postRow.caption || '').trim() ? String(postRow.caption) : rawCaption;

return [{
  json: {
    dl_ok: true,
    errCode: '',
    errStage: '',
    errMsg: '',
    items: rawItems,
    nextIdx: 0,
    uploadedAssets: [],
    totalBytes: 0,
    imgCount: 0,
    vidCount: 0,
    sourceId: String(dl.sourceId || dl.source_id || dl.shortcode || postRow.source_id || ''),
    metadata: {
      original_caption: rawCaption,
      caption: effectiveCaption,
      caption_status: captionStatus,
      caption_source: String(dl.captionSource || dl.caption_source || (rawCaption ? 'structured' : 'none')),
      canonical_url: String(dl.canonicalUrl || dl.canonical_url || req.source_instagram_url),
      source_username: String(dl.username || dl.sourceUsername || dl.ownerUsername || ''),
      source_kind: String(dl.kind || dl.sourceKind || dl.source_kind || ''),
      hashtags: Array.isArray(dl.hashtags) ? dl.hashtags : extractTags(rawCaption, '#'),
      mentions: Array.isArray(dl.mentions) ? dl.mentions : extractTags(rawCaption, '@'),
      source_published_at: (dl.postMetadata || {}).publishedAt || dl.publishedAt || dl.source_published_at || '',
      source_like_count: (dl.postMetadata || {}).likeCount ?? dl.likeCount ?? '',
      source_comment_count: (dl.postMetadata || {}).commentCount ?? dl.commentCount ?? '',
      source_play_count: (dl.postMetadata || {}).playCount ?? dl.playCount ?? '',
      source_metadata: dl.postMetadata || dl.metadata || {},
      post_media_type: String(postRow.media_type || ''),
      dl_media_type: String(dl.mediaType || '')
    }
  }
}];

function safeSlug(val) { return String(val || 'item').replace(/[^A-Za-z0-9_-]+/g, '_').slice(0, 48); }

var req = $('CODE | Validate & Safeguard').first().json;
var prevOutcome = $input.first().json || {};
var state = (prevOutcome._loop && prevOutcome._loop.items) ? prevOutcome._loop : $('CODE | Validate Downloader & Init Upload Loop').first().json;
var idx = Number(state.nextIdx || 0);
var items = Array.isArray(state.items) ? state.items : [];
var itemObj = items[idx] || {};


var srcUrl = String(itemObj.url || itemObj.downloadUrl || itemObj.media_url || itemObj.secure_url || '').trim();
var rawKind = String(itemObj.type || itemObj.media_type || itemObj.kind || (state.metadata && state.metadata.dl_media_type) || (state.metadata && state.metadata.post_media_type) || '').toUpperCase();
var isVideo = rawKind.indexOf('VIDEO') !== -1 || rawKind.indexOf('REEL') !== -1 || /\.mp4(\?|$)/i.test(srcUrl);
var resType = isVideo ? 'video' : 'image';
var publicId = 'instaops-v2/' + safeSlug(req.post_uuid) + '/item_' + idx + '_' + (state.sourceId ? safeSlug(state.sourceId) : 'src');

return [{
  json: {
    up_ready: true,
    upload_url: 'https://api.cloudinary.com/v1_1/' + encodeURIComponent(req.cld_cloud) + '/' + resType + '/upload',
    src_url: srcUrl,
    is_video: isVideo,
    res_type: resType,
    asset_media_type: isVideo ? 'VIDEO' : 'IMAGE',
    public_id: publicId,
    item_obj: itemObj,
    idx: idx,
    _loop: state
  }
}];

var req = $('CODE | Validate & Safeguard').first().json;
var prep = $('CODE | Prepare Next Cloudinary Upload').last().json;
var state = Object.assign({}, prep._loop);
var uploadedAssets = Array.isArray(state.uploadedAssets) ? state.uploadedAssets.slice() : [];
var raw = $input.first().json || {};
var netErr = Boolean(raw.error && raw.statusCode === undefined);
var sc = raw.statusCode !== undefined ? Number(raw.statusCode) : (netErr ? 0 : 200);
var upBody = raw.body !== undefined ? raw.body : raw;
if (typeof upBody === 'string') { try { upBody = JSON.parse(upBody); } catch (_) { upBody = {}; } }
upBody = upBody || {};

var idx = Number(prep.idx || 0);
if (netErr || sc >= 300 || upBody.error || !upBody.secure_url || !upBody.public_id || !upBody.asset_id || String(upBody.public_id)!==String(prep.public_id) || String(upBody.resource_type)!==String(prep.res_type)) {
  var errMsg = netErr ? String(raw.error.message || 'network error') : ((upBody.error && upBody.error.message) || ('Cloudinary upload failed at index ' + idx + ' (HTTP ' + sc + ')'));
  state.uploadedAssets = uploadedAssets;
  return [{ json: { loop_done: true, upload_failed: true, errCode: 'CLOUDINARY_UPLOAD_FAILED', errStage: 'UPLOADING_MEDIA', errMsg: errMsg + ' (' + uploadedAssets.length + ' prior checkpointed)', _loop: state } }];
}

if (!String(upBody.secure_url).startsWith('https://res.cloudinary.com/' + req.cld_cloud + '/')) {
  state.uploadedAssets = uploadedAssets;
  return [{ json: { loop_done: true, upload_failed: true, errCode: 'SSRF_BLOCKED', errStage: 'UPLOADING_MEDIA', errMsg: 'Cloudinary returned unexpected host for asset ' + idx, _loop: state } }];
}

var itemObj = prep.item_obj || {};
var isVid = Boolean(prep.is_video);
var fSize = Number(upBody.bytes || itemObj.fileSizeBytes || 0) || 0;
uploadedAssets.push({
  internal_asset_id: 'ast_' + req.post_id + '_' + idx,
  media_index: idx,
  media_type: prep.asset_media_type,
  resource_type: prep.res_type,
  delivery_type: String(upBody.type || 'upload'),
  source_expires_at: String(itemObj.expiresAt || itemObj.expires_at || ''),
  cloudinary_public_id: String(upBody.public_id),
  cloudinary_asset_id: String(upBody.asset_id || ''),
  secure_url: String(upBody.secure_url),
  thumbnail_url: String(itemObj.thumbnailUrl || itemObj.thumbnail_url || (isVid ? String(upBody.secure_url).replace(/\.mp4(\?.*)?$/i, '.jpg') : upBody.secure_url)),
  format: String(upBody.format || (isVid ? 'mp4' : 'jpg')),
  file_size_bytes: fSize,
  width: upBody.width || null,
  height: upBody.height || null,
  duration: upBody.duration || itemObj.duration || null,
  storage_status: 'ACTIVE',
  error: ''
});

state.uploadedAssets = uploadedAssets;
state.nextIdx = idx + 1;
state.totalBytes = Number(state.totalBytes || 0) + fSize;
state.imgCount = Number(state.imgCount || 0) + (isVid ? 0 : 1);
state.vidCount = Number(state.vidCount || 0) + (isVid ? 1 : 0);

var done = state.nextIdx >= state.items.length;
return [{ json: { loop_done: done, upload_failed: false, errCode: '', errStage: '', errMsg: '', _loop: state } }];
